const listCbtProctorEventsBySession = `-- name: ListCbtProctorEventsBySession :many
SELECT
  ev.id,
  ev.participant_id,
  ep.student_id,
  s.nis,
  s.nama,
  ep.session_id,
  ep.room_id,
  COALESCE(r.room_name, '') AS room_name,
  ev.event_type,
  ev.severity,
  ev.category,
  ev.risk_delta,
  ev.dedup_key,
  ev.event_data,
  ev.created_at,
  ev.acknowledged_at,
  ev.acknowledged_by,
  ev.acknowledge_note,
  ev.requires_note,
  ev.actor_username_snapshot
FROM cbt_participant_events ev
JOIN cbt_exam_participants ep ON ep.id = ev.participant_id
JOIN students s ON s.id = ep.student_id
LEFT JOIN cbt_exam_rooms r ON r.id = ep.room_id
WHERE ep.session_id = $1
  AND ($2::uuid IS NULL OR ev.participant_id = $2::uuid)
ORDER BY ev.created_at DESC
LIMIT $3
`

